            full_code: "def lcs_length(s1: str, s2: str, i: int, j: int, dp) -> str :\n    if i == 0 or j == 0:\n        return 0\n    if dp[i][j] != -1:\n        return dp[i][j]\n    \n    if s1[i-1] == s2[j-1]:\n        dp[i][j] = 1 + lcs_length(i-1, j-1)\n    else:\n        dp[i][j] = max(lcs_length(i-1, j), lcs_length(i, j-1))\n    return dp[i][j]\n\n\ndef main():\n    s1 = 'geek'\n    s2 = 'eke'\n    n = len(s1)\n    m = len(s2)\n    dp = [ [''] * (m+1) for _ in range(n+1)]\n    x = lcs_length(s1, s2, len(s1), len(s2), dp)\n    result = []\n    i, j = n, m\n    while i > 0 and j > 0:\n        if s1[i-1] == s2[j-1]:\n            result.append(s1[i-1])\n            i -= 1\n            j -= 1\n        elif dp[i-1][j] > dp[i][j-1]:\n            result.append(s1[i-1])\n            i -= 1\n        else:\n            result.append(s2[j-1])\n            j -= 1\n    \n    while i > 0:\n        result.append(s1[i-1])\n        i -= 1\n    while j > 0:\n        result.append(s2[j-1])\n        j -= 1\n    \n    return ''.join(reversed(result))\n\n        \nprint(main())\n    ",
