            full_code: "# Concept: https://www.youtube.com/watch?v=aBxjDBC4M1U\n\nclass DisjointSet:\n    def __init__(self, n):\n        self.rank = [0 for _ in range(n)]\n        self.parent = [i for i in range(n)]\n\n    def unionByRank(self, u, v):\n        pu, pv = self.findUltParent(u), self.findUltParent(v)\n        if self.rank[pu] == self.rank[pv]:\n            self.rank[pu] += 1\n            self.parent[pv] = pu\n        elif self.rank[pu] < self.rank[pv]:\n            self.parent[pu] = pv\n        else:\n            self.parent[pv] = pu\n        \n    \n    def findUltParent(self, u):\n        if self.parent[u] == u:\n            return u\n        self.parent[u] = self.findUltParent(self.parent[u])\n        return self.parent[u]\n\n\ndef main():\n    d = DisjointSet(5)\n    d.unionByRank(0,1)\n    d.unionByRank(0,2)\n    d.unionByRank(3,4)\n    d.unionByRank(2,3)\n    # print(d.findUltParent(3))\n    # print(d.findUltParent(5))\n    print(d.parent)\nif __name__ == \"__main__\":\n    main()\n\n",
