            full_code: "class TreeNode:\n    def __init__(self, val = 0, left = None, right = None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef inorder(root: TreeNode, res = []):\n    if root is not None:\n        inorder(root.left, res)\n        res.append(root.val)\n        inorder(root.right, res)\n    return res\n\ndef inorder_nonrecursive(root: TreeNode):\n    res = []\n    stack = []\n    while(1):\n        while(root):\n            stack.append(root)\n            root = root.left\n        if len(stack) == 0:\n            break\n        res.append(stack.pop().val)\n        root = root.right\n    return res\n\n\ndef preorder(root: TreeNode, res = []):\n    if root is not None:\n        res.append(root.val)\n        preorder(root.left)\n        preorder(root.right)\n    return res\n\ndef preorder_nonrecursive(root: TreeNode):\n    res = []\n    stack = []\n    while(1):\n        while(root):\n            res.append(root.val)\n            stack.append(root)\n            root = root.left\n        if len(stack) == 0:\n            break\n        root = stack.pop()\n        root = root.right\n\ndef postorder(root: TreeNode, res = []):\n    if root is not None:\n        \n        postorder(root.left)\n        postorder(root.right)\n        res.append(root.val)\n    return res\n\ndef postorder_nonrecursive(root: TreeNode):\n    res = []\n    stack = []\n    while(1):\n        while(root):\n            stack.append(root)\n            root = root.left\n        if len(stack) == 0:\n            break\n        while(not root.left and not root.right):\n            res.append(stack.pop().val)\n        root = stack[-1]\n        if(not root.left and not root.right):\n            res.append(stack.pop().val)\n        root = root.right",
